# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 250" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="250" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">GELENEKSEL ÜRETİMDEN SANAYİ DEVRİMİ\'NE GEÇİŞ</text>\n  <rect x="20" y="48" width="305" height="182" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <rect x="20" y="48" width="305" height="32" rx="10" fill="#d97706"/>\n  <text x="172" y="69" text-anchor="middle" font-size="12" font-weight="bold" fill="#ffffff">SANAYİ ÖNCESİ (Geleneksel Üretim)</text>\n  <text x="172" y="100" text-anchor="middle" font-size="11" font-weight="bold" fill="#78350f">• Enerji: İnsan, hayvan, rüzgâr ve su gücü</text>\n  <text x="172" y="126" text-anchor="middle" font-size="11" font-weight="bold" fill="#78350f">• Mekân: Ev, küçük el tezgâhı ve lonca atölyesi</text>\n  <text x="172" y="152" text-anchor="middle" font-size="11" font-weight="bold" fill="#78350f">• Üretim Hızı: Yavaş, sınırlı ve yüksek maliyetli</text>\n  <text x="172" y="178" text-anchor="middle" font-size="11" font-weight="bold" fill="#78350f">• Nüfus Yapısı: Kırsal / tarımsal nüfus ağırlıklı</text>\n  <text x="172" y="208" text-anchor="middle" font-size="10.5" fill="#92400e">Usta-kalfa-çırak ilişkisi ve yerel pazar</text>\n\n  <line x1="330" y1="138" x2="365" y2="138" stroke="#1e293b" stroke-width="2.5"/>\n  <polygon points="365,133 375,138 365,143" fill="#1e293b"/>\n\n  <rect x="375" y="48" width="305" height="182" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <rect x="375" y="48" width="305" height="32" rx="10" fill="#2563eb"/>\n  <text x="527" y="69" text-anchor="middle" font-size="12" font-weight="bold" fill="#ffffff">SANAYİ SONRASI (Modern Fabrika)</text>\n  <text x="527" y="100" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">• Enerji: Buhar makinesi (James Watt) ve kömür</text>\n  <text x="527" y="126" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">• Mekân: Büyük ölçekli makineli fabrikalar</text>\n  <text x="527" y="152" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">• Üretim Hızı: Seri, standart ve düşük maliyetli</text>\n  <text x="527" y="178" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">• Nüfus Yapısı: Hızlı kentleşme ve göç</text>\n  <text x="527" y="208" text-anchor="middle" font-size="10.5" fill="#1d4ed8">Sermaye sahibi (burjuva) - ücretli işçi ayrımı</text>\n</svg>', '<svg viewBox="0 0 700 250" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="250" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">SANAYİ DEVRİMİ\'NİN EKONOMİK, TOPLUMSAL VE SİYASİ SONUÇLARI</text>\n  <rect x="18" y="52" width="212" height="176" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <rect x="18" y="52" width="212" height="30" rx="10" fill="#dc2626"/>\n  <text x="124" y="72" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#ffffff">SİYASİ &amp; KÜRESEL BOYUT</text>\n  <text x="124" y="102" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#7f1d1d">• Ham Madde ve Pazar Arayışı</text>\n  <text x="124" y="126" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#7f1d1d">• Modern Sömürgecilik Yarışı</text>\n  <text x="124" y="150" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#7f1d1d">• Buharlı Gemi ve Demiryolu Ağı</text>\n  <text x="124" y="174" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#7f1d1d">• Küresel Güç Dengesinin</text>\n  <text x="124" y="190" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#7f1d1d">Avrupa Lehine Değişmesi</text>\n\n  <rect x="244" y="52" width="212" height="176" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <rect x="244" y="52" width="212" height="30" rx="10" fill="#16a34a"/>\n  <text x="350" y="72" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#ffffff">TOPLUMSAL &amp; FİKRÎ BOYUT</text>\n  <text x="350" y="102" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#14532d">• Kırdan Kente Göç &amp; Kentleşme</text>\n  <text x="350" y="126" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#14532d">• İşçi Sınıfının (Proletarya) Doğuşu</text>\n  <text x="350" y="150" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#14532d">• Sendikacılık ve İşçi Hakları</text>\n  <text x="350" y="174" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#14532d">• Kapitalizm ve Sosyalizm</text>\n  <text x="350" y="190" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#14532d">Akımlarının Yükselişi</text>\n\n  <rect x="470" y="52" width="212" height="176" rx="10" fill="#f3e8ff" stroke="#7c3aed" stroke-width="2"/>\n  <rect x="470" y="52" width="212" height="30" rx="10" fill="#7c3aed"/>\n  <text x="576" y="72" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#ffffff">OSMANLI EKONOMİSİNE ETKİ</text>\n  <text x="576" y="102" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#4c1d95">• Ucuz Avrupa Mallarının Girişi</text>\n  <text x="576" y="126" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#4c1d95">• Lonca ve El Tezgâhlarının</text>\n  <text x="576" y="142" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#4c1d95">Rekabet Gücünü Yitirmesi</text>\n  <text x="576" y="168" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#4c1d95">• Ham Madde Satan ve Mamul</text>\n  <text x="576" y="184" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#4c1d95">Mal Alan Açık Pazar Konumu</text>\n</svg>', '<svg viewBox="0 0 700 250" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="250" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">DEĞİŞEN DÜNYADA OSMANLI (1683-1789) KRONOLOJİK ÖZET TABLOSU</text>\n  <rect x="20" y="48" width="660" height="182" rx="8" fill="#ffffff" stroke="#cbd5e1" stroke-width="1.8"/>\n  <rect x="20" y="48" width="660" height="32" rx="8" fill="#1e3a8a"/>\n  <text x="115" y="69" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#ffffff">Tarih / Dönüm Noktası</text>\n  <text x="395" y="69" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#ffffff">Siyasi, Askerî ve Ekonomik Önemi</text>\n\n  <text x="115" y="98" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1e40af">1683 Viyana &amp; 1699 Karlofça</text>\n  <text x="395" y="98" text-anchor="middle" font-size="10.5" fill="#0f172a">İlk büyük toprak kaybı; fetih politikasından savunma diplomasisine geçiş</text>\n\n  <text x="115" y="126" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">1711 Prut &amp; 1718 Pasarofça</text>\n  <text x="395" y="126" text-anchor="middle" font-size="10.5" fill="#0f172a">Azak\'ın geri alınışı (Prut); Batı\'ya yöneliş ve Lale Devri ıslahatları (1718-1730)</text>\n\n  <text x="115" y="154" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#7c3aed">1739 Belgrad Antlaşması</text>\n  <text x="395" y="154" text-anchor="middle" font-size="10.5" fill="#0f172a">18. yüzyıldaki son kazançlı antlaşma; Fransa\'ya kapitülasyonların sürekli kılınması (1740)</text>\n\n  <text x="115" y="182" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b91c1c">1774 Küçük Kaynarca</text>\n  <text x="395" y="182" text-anchor="middle" font-size="10.5" fill="#0f172a">Kırım\'ın kaybı, Karadeniz\'de Rus donanması, ilk savaş tazminatı ve halifelik nüfuzu</text>\n\n  <text x="115" y="212" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b45309">Avrupa\'da Dönüşüm</text>\n  <text x="395" y="212" text-anchor="middle" font-size="10.5" fill="#0f172a">Bilim Devrimi, Aydınlanma Çağı ve İngiltere merkezli Sanayi Devrimi (Buhar gücü)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
